import React from "react";
import { Users, Trophy, Shield, GraduationCap } from "lucide-react";

interface StatItem {
  label: string;
  value: number | string;
  icon: "users" | "trophy" | "men" | "women" | "college";
  description?: string;
}

interface StatCounterProps {
  stats: {
    totalPlayers: number;
    olympians: number;
    mensCount: number;
    womensCount: number;
    collegesCount: number;
  };
}

export function StatCounter({ stats }: StatCounterProps) {
  const items: StatItem[] = [
    {
      label: "Indexed Players",
      value: stats.totalPlayers,
      icon: "users",
      description: "USA national sevens pool",
    },
    {
      label: "USA Olympians",
      value: stats.olympians,
      icon: "trophy",
      description: "Rio, Tokyo & Paris Games",
    },
    {
      label: "Men's Eagles 7s",
      value: stats.mensCount,
      icon: "men",
      description: "Captains & World Series stars",
    },
    {
      label: "Women's Eagles 7s",
      value: stats.womensCount,
      icon: "women",
      description: "SVNS medalists & pioneers",
    },
    {
      label: "College Programs",
      value: stats.collegesCount,
      icon: "college",
      description: "Collegiate feeder pathways",
    },
  ];

  const getIcon = (type: StatItem["icon"]) => {
    switch (type) {
      case "users":
        return <Users className="w-5 h-5 text-blue-700 dark:text-blue-400" />;
      case "trophy":
        return <Trophy className="w-5 h-5 text-amber-500" />;
      case "men":
        return <Shield className="w-5 h-5 text-blue-800 dark:text-blue-300" />;
      case "women":
        return <Shield className="w-5 h-5 text-rose-700 dark:text-rose-300" />;
      case "college":
        return <GraduationCap className="w-5 h-5 text-amber-600 dark:text-amber-400" />;
    }
  };

  return (
    <div className="grid grid-cols-2 md:grid-cols-5 gap-3 sm:gap-4 w-full">
      {items.map((item, idx) => (
        <div
          key={idx}
          className={`flex flex-col justify-between p-4 sm:p-5 rounded-2xl border border-border bg-card shadow-xs transition-all hover:border-blue-500/40 ${
            idx === 4 ? "col-span-2 md:col-span-1" : ""
          }`}
        >
          <div className="flex items-center justify-between gap-2 mb-3">
            <span className="text-xs font-semibold text-muted-foreground uppercase tracking-wider line-clamp-1">
              {item.label}
            </span>
            <div className="p-1.5 rounded-xl bg-secondary/80 flex-shrink-0">
              {getIcon(item.icon)}
            </div>
          </div>

          <div>
            <div className="text-2xl sm:text-3xl font-black text-foreground tracking-tight">
              {typeof item.value === "number" ? item.value.toLocaleString() : item.value}
            </div>
            {item.description && (
              <p className="text-[11px] text-muted-foreground mt-1 line-clamp-1">
                {item.description}
              </p>
            )}
          </div>
        </div>
      ))}
    </div>
  );
}
